/*!50003 CREATE*/ /*!50017 DEFINER=`sa`@`%`*/ /*!50003 TRIGGER utrigger_Rera_Complaint_NoticeFiveNine_HearingRecord_INSERT 
AFTER INSERT ON tbl_rera_webapplication_noticessectionlockcodefivenine 
FOR EACH ROW
BEGIN
   
	DECLARE v_Related_ComplaintNoticesSectionFiveNine_ID bigint(20); 
	Declare v_Related_ComplaintNoticesSectionFiveNine_Code varchar(50);
	Declare v_TypeOfComplaint varchar(50);   
	Declare v_TypeOfHearing varchar(50); 
	Declare v_TypeOfComplaintHearing varchar(50); 

	Declare v_Bench_HearingDate datetime(3);
	Declare v_Bench_HearingTime varchar(90);
	Declare v_HearingBench_ID varchar(150);
	Declare v_HearingBench_Name varchar(150);
	Declare v_HearingBench_FixedFor_ID varchar(150);
	Declare v_HearingBench_FixedFor_Name varchar(150);    
	Declare v_HearingBench_BussinesOnDate_ProceedingDate datetime(3);
	Declare v_Remarks_IfAny varchar(1500);

	Declare v_CreatedBy varchar(50);
	Declare v_CreatedOn datetime(3);
	Declare v_ModifyBy varchar(50);
	Declare v_ModifyOn datetime(3);
    
    Declare v_getHearingRecords_Count int;
    Declare v_getBenchHearingDate_ID bigint(20);
    Declare v_getHearing_SequenceOrderID int;
    
    -- Assign Values
	SET v_Related_ComplaintNoticesSectionFiveNine_ID=NEW.NoticesSectionFiveNine_ID;         
	SET v_Related_ComplaintNoticesSectionFiveNine_Code=NEW.NoticesSectionFiveNine_IDName;           
	SET v_TypeOfComplaint=NEW.IsPersonalHearing;            
	SET v_TypeOfHearing=NEW.FixedFor; 
	SET v_TypeOfComplaintHearing=udfn_GetComplaint_UnderSection(NEW.FixedFor);
	
	SET v_Bench_HearingDate=NEW.OrderDate;
	SET v_Bench_HearingTime=NEW.OrderTime;
	SET v_HearingBench_ID=NEW.HearingBenchCode;
	SET v_HearingBench_Name=NEW.HearingBenchName;
	SET v_HearingBench_FixedFor_ID=NEW.CurrentEvent_IdentifiedCode;
	SET v_HearingBench_FixedFor_Name=NEW.CurrentEvent_IdentifiedAggregateName;
	SET v_HearingBench_BussinesOnDate_ProceedingDate=NEW.CurrentStatusDate;
	SET v_Remarks_IfAny=NEW.OrderDateWithRemarksIfAny;
  
	SET v_CreatedBy=NEW.CreatedBy;
	SET v_CreatedOn=NEW.CreatedOn;


-- Application ID
select max(BenchHearingDate_ID) into v_getBenchHearingDate_ID from tbl_rera_complaint_sectionfivenine_prehearingdate;
IF (v_getBenchHearingDate_ID IS NULL)      
then      
	set v_getBenchHearingDate_ID=1;
ELSE       
	set v_getBenchHearingDate_ID=v_getBenchHearingDate_ID+1;
end if;

-- Application Sequence Order
select max(HearingStatus) into v_getHearing_SequenceOrderID from tbl_rera_complaint_sectionfivenine_prehearingdate where Related_ComplaintNoticesSectionFiveNine_ID=v_Related_ComplaintNoticesSectionFiveNine_ID;
IF (v_getHearing_SequenceOrderID IS NULL)      
then      
	set v_getHearing_SequenceOrderID=1;
ELSE       
	set v_getHearing_SequenceOrderID=v_getHearing_SequenceOrderID+1;
end if;


select count(BenchHearingDate_ID) into v_getHearingRecords_Count from tbl_rera_complaint_sectionfivenine_prehearingdate 
where Related_ComplaintNoticesSectionFiveNine_ID=v_Related_ComplaintNoticesSectionFiveNine_ID and IsActive=1;

-- Hearing/Order/NA Deatils
IF (v_TypeOfComplaint=2) THEN
	set v_Bench_HearingTime='00:00';
END IF;

-- Hearing/Order Date Only
IF (v_TypeOfComplaint<>0) THEN
	-- Hearing Record
	IF (v_getHearingRecords_Count<>0) THEN
		-- Hearing Record Exist
		
		update tbl_rera_complaint_sectionfivenine_prehearingdate set IsActive=2 
		where Related_ComplaintNoticesSectionFiveNine_ID=v_Related_ComplaintNoticesSectionFiveNine_ID and IsActive=1;
		
		Insert into tbl_rera_complaint_sectionfivenine_prehearingdate   
		(
		-- BenchHearingDate_IndexID,
		BenchHearingDate_ID,
		Related_ComplaintNoticesSectionFiveNine_ID,
		Related_ComplaintNoticesSectionFiveNine_Code,
		TypeOfComplaint,
		TypeOfHearing,
		TypeOfComplaintHearing,
		Bench_HearingDate,
		Bench_HearingTime,
		HearingBench_ID,
		HearingBench_Name,
		HearingBench_FixedFor_ID,
		HearingBench_FixedFor_Name,
		HearingReplyDays,
		HearingBench_BussinesOnDate_ProceedingDate,
		HearingStatus,
		Remarks_IfAny,
		A_column,
		B_column,
		C_column,
		D_column,
		E_column,
		IsActive,
		IsDraft,
		IsLock,
		IsPublicView,
		CreatedBy,
		CreatedOn,
		ModifyBy,
		ModifyOn
		)  
		values  
		(   
		-- BenchHearingDate_IndexID,
		v_getBenchHearingDate_ID, -- BenchHearingDate_ID,
		v_Related_ComplaintNoticesSectionFiveNine_ID,
		v_Related_ComplaintNoticesSectionFiveNine_Code,
		v_TypeOfComplaint,
		v_TypeOfHearing,
		v_TypeOfComplaintHearing,
		v_Bench_HearingDate,
		v_Bench_HearingTime,
		v_HearingBench_ID,
		v_HearingBench_Name,
		v_HearingBench_FixedFor_ID,
		v_HearingBench_FixedFor_Name,
		0, -- HearingReplyDays,
		v_HearingBench_BussinesOnDate_ProceedingDate,
		v_getHearing_SequenceOrderID, -- HearingStatus,
		v_Remarks_IfAny,
		null, -- A_column,
		null, -- B_column,
		null, -- C_column,
		null, -- D_column,
		null, -- E_column,
		1, -- IsActive,
		1, -- IsDraft,
		1, -- IsLock,
		1, -- IsPublicView,
		v_CreatedBy,
		v_CreatedOn,
		'sysadmin', -- ModifyBy,
		NOW() -- ModifyOn
		);

	ELSE
		-- First Hearing Record
		Insert into tbl_rera_complaint_sectionfivenine_prehearingdate   
		(
		-- BenchHearingDate_IndexID,
		BenchHearingDate_ID,
		Related_ComplaintNoticesSectionFiveNine_ID,
		Related_ComplaintNoticesSectionFiveNine_Code,
		TypeOfComplaint,
		TypeOfHearing,
		TypeOfComplaintHearing,
		Bench_HearingDate,
		Bench_HearingTime,
		HearingBench_ID,
		HearingBench_Name,
		HearingBench_FixedFor_ID,
		HearingBench_FixedFor_Name,
		HearingReplyDays,
		HearingBench_BussinesOnDate_ProceedingDate,
		HearingStatus,
		Remarks_IfAny,
		A_column,
		B_column,
		C_column,
		D_column,
		E_column,
		IsActive,
		IsDraft,
		IsLock,
		IsPublicView,
		CreatedBy,
		CreatedOn,
		ModifyBy,
		ModifyOn
		)  
		values  
		(   
		-- BenchHearingDate_IndexID,
		v_getBenchHearingDate_ID, -- BenchHearingDate_ID,
		v_Related_ComplaintNoticesSectionFiveNine_ID,
		v_Related_ComplaintNoticesSectionFiveNine_Code,
		v_TypeOfComplaint,
		v_TypeOfHearing,
		v_TypeOfComplaintHearing,
		v_Bench_HearingDate,
		v_Bench_HearingTime,
		v_HearingBench_ID,
		v_HearingBench_Name,
		v_HearingBench_FixedFor_ID,
		v_HearingBench_FixedFor_Name,
		0, -- HearingReplyDays,
		v_HearingBench_BussinesOnDate_ProceedingDate,
		v_getHearing_SequenceOrderID, -- HearingStatus,
		v_Remarks_IfAny,
		null, -- A_column,
		null, -- B_column,
		null, -- C_column,
		null, -- D_column,
		null, -- E_column,
		1, -- IsActive,
		1, -- IsDraft,
		1, -- IsLock,
		1, -- IsPublicView,
		v_CreatedBy,
		v_CreatedOn,
		'sysadmin', -- ModifyBy,
		NOW() -- ModifyOn
		);
	END IF;
END IF;
   
END */;;
DELIMITER ;
